 const ui=document.createElement('div');ui.id='diningUI';ui.className='hidden';ui.innerHTML=`<div id="guestBubbles"></div><div id="diningInfo" role="status"></div><div id="diningControls"><div class="dining-side"><button id="backKitchen">↙ 回灶台</button></div><div class="dining-side"><button id="chooseSoy">拿豆浆壶</button><button id="throwFood" class="hidden">准备上菜</button><button id="fanGuest" class="hidden">扇风</button><button id="pourSoy" class="hidden">倒豆浆</button><button id="enableBreath" class="hidden">开启吹气</button></div></div>`;$('kitchen').append(ui);const ending=document.createElement('div');ending.id='shiftEnd';ending.className='hidden';ending.innerHTML=`<section class="closing-card" role="dialog" aria-modal="true" aria-labelledby="closingTitle"><div class="party">🎉 🥳 🎊</div><h2 id="closingTitle">太好了，没有顾客了。</h2><p>可以收工了！</p><button id="restartStall">重新开始摆摊</button></section>`;for(let i=0;i<36;i++){const piece=document.createElement('i');piece.className='confetti';piece.style.cssText=`--x:${i*2.8}%;--c:${['#bc5442','#e9c35d','#7e9858','#679cb0'][i%4]};--duration:${3+i%4}s;--delay:${-i*.17}s`;ending.append(piece);}$('kitchen').append(ending);$('restartStall').onclick=()=>this.restartStall();
